head.b:skin:
/* ==========================================================================
   MEIWATV - UNIFIED THEATER LIVE STREAMING PORTAL
   ========================================================================== */
:root {
  --bg-dark: #070a10;
  --bg-card: #0e1422;
  --bg-card-hover: #162035;
  --bg-surface: #121929;
  --bg-header: #05080e;

  --primary-green: #10b981;
  --primary-neon: #00eb1f;
  --primary-glow: rgba(16, 185, 129, 0.35);

  --accent-gold: #ffe400;
  --accent-red: #ef4444;
  --accent-red-glow: rgba(239, 68, 68, 0.4);

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;

  --border-subtle: rgba(255, 255, 255, 0.08);
  --border-hover: rgba(16, 185, 129, 0.5);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --font-main: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'Outfit', sans-serif;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* SITE HEADER */
.site-header {
  background: var(--bg-header);
  border-bottom: 1px solid var(--border-subtle);
  position: sticky;
  top: 0;
  z-index: 1000;
  backdrop-filter: blur(12px);
}

.nav-container {
  max-width: 1540px;
  margin: 0 auto;
  padding: 0 16px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.brand-logo {
  display: flex;
  align-items: center;
  text-decoration: none;
  flex-shrink: 0;
}

.brand-logo-img {
  height: 38px;
  width: auto;
  object-fit: contain;
}

/* Navigation Header Tabs */
.nav-menu-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 4px 0;
}
.nav-menu-links::-webkit-scrollbar { display: none; }

.nav-item-btn {
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-muted);
  font-family: var(--font-heading);
  font-size: 13.5px;
  font-weight: 700;
  padding: 7px 12px;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: var(--transition);
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  text-decoration: none;
}

.nav-item-btn:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.06);
}

.nav-item-btn.active {
  color: #000;
  background: var(--primary-green);
  border-color: var(--primary-green);
  box-shadow: 0 0 12px var(--primary-glow);
}

.nav-item-btn.btn-nav-live.active {
  background: var(--accent-red);
  color: #fff;
  border-color: var(--accent-red);
  box-shadow: 0 0 12px var(--accent-red-glow);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.btn-saweria-top {
  background: rgba(255, 228, 0, 0.12);
  border: 1px solid rgba(255, 228, 0, 0.3);
  color: var(--accent-gold);
  font-weight: 700;
  font-size: 12.5px;
  padding: 6px 12px;
  border-radius: var(--radius-full);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: var(--transition);
}
.btn-saweria-top:hover {
  background: var(--accent-gold);
  color: #000;
}

.btn-apk-top {
  background: linear-gradient(135deg, #10b981, #059669);
  color: #fff;
  font-weight: 800;
  font-size: 12.5px;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 6px;
  box-shadow: 0 2px 10px rgba(16, 185, 129, 0.3);
  transition: var(--transition);
}
.btn-apk-top:hover {
  filter: brightness(1.1);
  transform: translateY(-1px);
}

/* SPONSOR BANNER */
.adsterra-banner-container {
  max-width: 1540px;
  margin: 12px auto 0 auto;
  padding: 0 16px;
}
.adsterra-wrapper-box {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 8px;
  text-align: center;
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* UNIFIED THEATER MAIN LAYOUT */
.main-theater-container {
  max-width: 1540px;
  margin: 14px auto 30px auto;
  padding: 0 16px;
}

.unified-theater-grid {
  display: grid;
  grid-template-columns: 1fr 390px;
  gap: 16px;
  align-items: start;
}

@media (max-width: 1100px) {
  .unified-theater-grid {
    grid-template-columns: 1fr;
  }
}

/* THEATER PLAYER BOX (LEFT COLUMN) */
.theater-player-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
}

.player-top-bar {
  padding: 10px 14px;
  background: rgba(0, 0, 0, 0.4);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.player-match-badge {
  display: flex;
  align-items: center;
  gap: 8px;
}

.live-indicator {
  background: var(--accent-red);
  color: #fff;
  font-size: 11px;
  font-weight: 800;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  gap: 5px;
  animation: pulseGlow 1.5s infinite;
}

@keyframes pulseGlow {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.85; transform: scale(0.98); }
}

.player-server-group {
  display: flex;
  align-items: center;
  gap: 6px;
}

.btn-server {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  font-size: 11.5px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.btn-server:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.1);
}
.btn-server.active {
  background: var(--primary-green);
  color: #000;
  border-color: var(--primary-green);
  font-weight: 800;
}

/* 16:9 VIDEO PLAYER CONTAINER */
.video-container-169 {
  position: relative;
  width: 100%;
  padding-top: 56.25%; /* 16:9 Aspect Ratio */
  background: #000;
}

.video-container-169 video,
.video-container-169 iframe,
.video-container-169 .player-stage-screen {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border: none;
  object-fit: contain;
}

.player-stage-screen {
  background: radial-gradient(circle at center, #162035 0%, #070a10 85%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 24px;
  z-index: 5;
}

.player-stage-league {
  color: var(--primary-green);
  font-weight: 800;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 6px;
}

.player-stage-title {
  font-family: var(--font-heading);
  font-size: clamp(18px, 3.5vw, 26px);
  font-weight: 900;
  color: #fff;
  margin-bottom: 8px;
  max-width: 90%;
}

.player-stage-time {
  color: var(--text-muted);
  font-size: 13.5px;
  margin-bottom: 20px;
}

.btn-play-stream-huge {
  background: linear-gradient(135deg, #10b981, #059669);
  color: #fff;
  border: none;
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 900;
  padding: 12px 28px;
  border-radius: var(--radius-full);
  cursor: pointer;
  box-shadow: 0 4px 20px rgba(16, 185, 129, 0.4);
  display: inline-flex;
  align-items: center;
  gap: 10px;
  transition: var(--transition);
}
.btn-play-stream-huge:hover {
  transform: scale(1.05);
  box-shadow: 0 6px 25px rgba(16, 185, 129, 0.6);
}

/* DETAILS BAR & DIRECT STREAM ACTIONS UNDER PLAYER */
.player-match-detail-bar {
  padding: 14px 18px;
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.player-detail-main-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.detail-match-teams {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-heading);
  font-size: 16px;
  font-weight: 800;
}

.detail-team-logo {
  width: 28px;
  height: 28px;
  object-fit: contain;
}

.detail-score-pill {
  background: #000;
  color: var(--accent-gold);
  padding: 2px 10px;
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 800;
  border: 1px solid rgba(255, 228, 0, 0.3);
}

.player-action-buttons {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.btn-copy-stream {
  background: linear-gradient(135deg, #10b981, #059669);
  color: #fff;
  border: 1px solid #10b981;
  font-family: var(--font-heading);
  font-size: 12.5px;
  font-weight: 800;
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  box-shadow: 0 2px 10px rgba(16, 185, 129, 0.3);
  transition: var(--transition);
}
.btn-copy-stream:hover {
  filter: brightness(1.15);
  transform: translateY(-1px);
}

.btn-open-source {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border-subtle);
  color: var(--text-main);
  font-size: 12px;
  font-weight: 700;
  padding: 7px 12px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  text-decoration: none;
  transition: var(--transition);
}
.btn-open-source:hover {
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
}

/* DIRECT STREAM LINK INPUT BOX */
.stream-link-box {
  display: flex;
  align-items: center;
  background: #000;
  border: 1px solid rgba(16, 185, 129, 0.35);
  border-radius: var(--radius-sm);
  padding: 3px 6px 3px 12px;
  gap: 8px;
}
.stream-link-tag {
  font-size: 11px;
  font-weight: 800;
  color: var(--primary-green);
  white-space: nowrap;
}
.stream-link-input {
  flex: 1;
  background: transparent;
  border: none;
  color: #cbd5e1;
  font-family: monospace;
  font-size: 11.5px;
  outline: none;
  width: 100%;
}
.btn-quick-copy {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 4px;
  cursor: pointer;
  transition: var(--transition);
  white-space: nowrap;
}
.btn-quick-copy:hover {
  background: var(--primary-green);
  color: #000;
}

/* TOAST NOTIFICATION */
.toast-notification {
  position: fixed;
  bottom: 24px;
  right: 24px;
  background: #0e1422;
  color: #fff;
  border: 1px solid var(--primary-green);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6), 0 0 15px var(--primary-glow);
  padding: 12px 20px;
  border-radius: var(--radius-md);
  font-size: 13px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 10px;
  z-index: 99999;
  transform: translateY(100px);
  opacity: 0;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  pointer-events: none;
}
.toast-notification.show {
  transform: translateY(0);
  opacity: 1;
  pointer-events: auto;
}

/* RIGHT COLUMN: INTERACTIVE PLAYLIST */
.interactive-playlist-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  height: calc(100vh - 120px);
  max-height: 720px;
  min-height: 480px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
}

.playlist-header-bar {
  padding: 12px 14px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  background: rgba(0, 0, 0, 0.25);
}

.playlist-header-title {
  font-family: var(--font-heading);
  font-size: 14.5px;
  font-weight: 800;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 6px;
}

.playlist-counter-badge {
  background: rgba(16, 185, 129, 0.15);
  color: var(--primary-green);
  border: 1px solid rgba(16, 185, 129, 0.3);
  font-size: 11px;
  font-weight: 800;
  padding: 2px 8px;
  border-radius: var(--radius-full);
}

.playlist-search-wrap {
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  position: relative;
}

.playlist-search-input {
  width: 100%;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 7px 12px 7px 32px;
  color: #fff;
  font-size: 12.5px;
  outline: none;
  transition: var(--transition);
}
.playlist-search-input:focus {
  border-color: var(--primary-green);
  box-shadow: 0 0 8px var(--primary-glow);
}
.playlist-search-icon {
  position: absolute;
  left: 22px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-dim);
  font-size: 12px;
}

.playlist-scroll-area {
  padding: 8px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

/* CATEGORY DIVIDER INSIDE PLAYLIST */
.playlist-category-divider {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px 4px 10px;
  margin-top: 4px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.playlist-divider-title {
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 800;
  color: var(--primary-green);
  display: flex;
  align-items: center;
  gap: 6px;
}
.playlist-divider-count {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 800;
  padding: 1px 6px;
  border-radius: var(--radius-full);
}

/* MATCH CARD ROW IN PLAYLIST */
.match-row-item {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 9px 12px;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.match-row-item:hover, .match-row-item.active {
  background: var(--bg-card-hover);
  border-color: var(--primary-green);
  transform: translateX(2px);
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
}

.match-row-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: var(--text-muted);
}
.match-row-league {
  color: var(--primary-green);
  font-weight: 700;
  max-width: 65%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.match-row-time {
  font-size: 10.5px;
  color: var(--text-muted);
}

.match-row-teams-grid {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}
.team-entry {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  font-size: 12.5px;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.team-entry.away {
  justify-content: flex-end;
  text-align: right;
}
.team-mini-logo {
  width: 20px;
  height: 20px;
  object-fit: contain;
  flex-shrink: 0;
}

.match-row-score-badge {
  background: #000;
  color: var(--accent-gold);
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 800;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 228, 0, 0.25);
  flex-shrink: 0;
}
.match-row-vs-badge {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.btn-copy-row-link {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  width: 26px;
  height: 26px;
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  cursor: pointer;
  transition: var(--transition);
  flex-shrink: 0;
}
.btn-copy-row-link:hover {
  background: var(--primary-green);
  color: #000;
  border-color: var(--primary-green);
  transform: scale(1.12);
  box-shadow: 0 0 10px var(--primary-glow);
}

/* HIDE UNWANTED BLOGGER STUFF */
.post-hidden-meta,
.event-link-preview,
.match-source-link {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
}
